import{_ as r}from"./chunks/管理后台.DGJthuhP.js";import{_ as e}from"./chunks/bpm-feature.COkSYXPy.js";import{_ as a,o as d,c as l,a2 as i}from"./chunks/framework.CqGPl1zp.js";const o="/newx-doc/img/%E8%A7%86%E9%A2%91%E6%95%99%E7%A8%8B/zsxq_bpm.png",n="/newx-doc/img/%E5%B7%A5%E4%BD%9C%E6%B5%81%E6%89%8B%E5%86%8C/%E5%8A%9F%E8%83%BD%E6%BC%94%E7%A4%BA/BPMN.png",h="/newx-doc/img/%E5%B7%A5%E4%BD%9C%E6%B5%81%E6%89%8B%E5%86%8C/%E5%8A%9F%E8%83%BD%E6%BC%94%E7%A4%BA/%E9%92%89%E9%92%89.png",s="/newx-doc/img/%E5%B7%A5%E4%BD%9C%E6%B5%81%E6%89%8B%E5%86%8C/%E5%8A%9F%E8%83%BD%E6%BC%94%E7%A4%BA/%E5%AE%A1%E6%89%B9%E7%95%8C%E9%9D%A2.png",k=JSON.parse('{"title":"工作流演示","description":"","frontmatter":{},"headers":[],"relativePath":"bpm-preview.md","filePath":"bpm-preview.md","lastUpdated":null}'),p={name:"bpm-preview.md"};function m(b,t,c,f,u,_){return d(),l("div",null,[...t[0]||(t[0]=[i('<h1 id="工作流演示" tabindex="-1">工作流演示 <a class="header-anchor" href="#工作流演示" aria-label="Permalink to &quot;工作流演示&quot;">​</a></h1><p>友情提示：BPM 全称是，业务流程管理（Business Process Management），实现工作流的功能</p><h2 id="_1-演示地址" tabindex="-1">1. 演示地址 <a class="header-anchor" href="#_1-演示地址" aria-label="Permalink to &quot;1. 演示地址&quot;">​</a></h2><h3 id="_1-1-bpm-管理后台" tabindex="-1">1.1 BPM 管理后台 <a class="header-anchor" href="#_1-1-bpm-管理后台" aria-label="Permalink to &quot;1.1 BPM 管理后台&quot;">​</a></h3><ul><li>演示地址：<a href="http://dashboard-vue3.yudao.iocoder.cn/" target="_blank" rel="noreferrer">http://dashboard-vue3.yudao.iocoder.cn/</a></li><li>菜单：“工作流程”下的「流程管理」「审批菜单」「OA 实例」等</li><li>仓库：<a href="https://github.com/yudaocode/yudao-ui-admin-vue3" target="_blank" rel="noreferrer">https://github.com/yudaocode/yudao-ui-admin-vue3</a> 的 <code>bpm</code> 目录，基于 Vue3 + Element Plus 实现</li></ul><p><img src="'+r+'" alt="管理后台"></p><h3 id="_1-2-bpm-后端" tabindex="-1">1.2 BPM 后端 <a class="header-anchor" href="#_1-2-bpm-后端" aria-label="Permalink to &quot;1.2 BPM 后端&quot;">​</a></h3><p>支持 Spring Boot 单体、Spring Cloud 微服务架构</p><ul><li>单体仓库：<a href="https://github.com/YunaiV/ruoyi-vue-pro" target="_blank" rel="noreferrer">https://github.com/YunaiV/ruoyi-vue-pro</a> 的 <code>yudao-module-bpm</code> 模块</li><li>微服务仓库：<a href="https://github.com/YunaiV/yudao-cloud" target="_blank" rel="noreferrer">https://github.com/YunaiV/yudao-cloud</a> 的 <code>yudao-module-bpm</code> 服务</li></ul><h2 id="_2-工作流启动" tabindex="-1">2. 工作流启动 <a class="header-anchor" href="#_2-工作流启动" aria-label="Permalink to &quot;2. 工作流启动&quot;">​</a></h2><p>参见 <a href="./bpm">《工作流手册 —— 功能开启》</a> 文档，一般 3 分钟就可以启动完成。</p><h2 id="_3-工作流交流" tabindex="-1">3. 工作流交流 <a class="header-anchor" href="#_3-工作流交流" aria-label="Permalink to &quot;3. 工作流交流&quot;">​</a></h2><p>专属交流社区，欢迎扫码加入。</p><p><img src="'+o+'" alt="示例流程"></p><p>微信扫描上方二维码，加入后可观看视频！</p><ul><li><a href="https://t.zsxq.com/04aqfIiY3" target="_blank" rel="noreferrer">01、如何集成 Flowable 框架？</a></li><li><a href="https://t.zsxq.com/04nun2RRz" target="_blank" rel="noreferrer">02、如何实现动态的流程表单？</a></li><li><a href="https://t.zsxq.com/04uneeaUb" target="_blank" rel="noreferrer">03、如何实现流程表单的保存？</a></li><li><a href="https://t.zsxq.com/04jiMrjAm" target="_blank" rel="noreferrer">04、如何实现流程表单的展示？</a></li><li><a href="https://t.zsxq.com/04iynUF6e" target="_blank" rel="noreferrer">05、如何实现流程模型的新建？</a></li><li><a href="https://t.zsxq.com/04rNVbEQB" target="_blank" rel="noreferrer">06、如何实现流程模型的流程图的设计？</a></li><li><a href="https://t.zsxq.com/042neybYz" target="_blank" rel="noreferrer">07、如何实现流程模型的流程图的预览？</a></li><li><a href="https://t.zsxq.com/04uburRvZ" target="_blank" rel="noreferrer">08、如何实现流程模型的分配规则？</a></li><li><a href="https://t.zsxq.com/04jUBMjyF" target="_blank" rel="noreferrer">09、如何实现流程模型的发布？</a></li><li><a href="https://t.zsxq.com/04MF6URvz" target="_blank" rel="noreferrer">10、如何实现流程定义的查询？</a></li><li><a href="https://t.zsxq.com/04jyvNfqj" target="_blank" rel="noreferrer">11、如何实现流程的发起？</a></li><li><a href="https://t.zsxq.com/046UFqRzz" target="_blank" rel="noreferrer">12、如何实现我的流程列表？</a></li><li><a href="https://t.zsxq.com/04aM72rzv" target="_blank" rel="noreferrer">13、如何实现流程的取消？</a></li><li><a href="https://t.zsxq.com/04rNvFI2f" target="_blank" rel="noreferrer">14、如何实现流程的任务分配？</a></li><li><a href="https://t.zsxq.com/04yFUVZvF" target="_blank" rel="noreferrer">15、如何实现会签、或签任务？</a></li><li><a href="https://t.zsxq.com/04QZzjAme" target="_blank" rel="noreferrer">16、如何实现我的待办任务列表？</a></li><li><a href="https://t.zsxq.com/04uj6AQJE" target="_blank" rel="noreferrer">17、如何实现我的已办任务列表？</a></li><li><a href="https://t.zsxq.com/04Q7UbqBM" target="_blank" rel="noreferrer">18、如何实现任务的审批通过？</a></li><li><a href="https://t.zsxq.com/04BQvJM7y" target="_blank" rel="noreferrer">19、如何实现任务的审批不通过？</a></li><li><a href="https://t.zsxq.com/04Ie2v7m2" target="_blank" rel="noreferrer">20、如何实现流程的审批记录？</a></li><li><a href="https://t.zsxq.com/04R72rzzN" target="_blank" rel="noreferrer">21、如何实现流程的流程图的高亮？</a></li><li><a href="https://t.zsxq.com/04eyRRJ2f" target="_blank" rel="noreferrer">22、如何实现工作流的短信通知？</a></li><li><a href="https://t.zsxq.com/04rFUjIei" target="_blank" rel="noreferrer">23、如何实现 OA 请假的发起？</a></li><li><a href="https://t.zsxq.com/04fMJiufQ" target="_blank" rel="noreferrer">24、如何实现 OA 请假的审批？</a></li></ul><h2 id="_4-功能描述" tabindex="-1">4. 功能描述 <a class="header-anchor" href="#_4-功能描述" aria-label="Permalink to &quot;4. 功能描述&quot;">​</a></h2><p><img src="'+e+'" alt="BPM 功能列表"></p><p>基于 Flowable 构建，可支持信创（国产）数据库，满足中国特色流程操作：</p><blockquote><p>历经头部企业生产验证，工作流引擎须标配仿钉钉/飞书 + BPMN 双设计器！！！</p><p>前者支持轻量配置简单流程，后者实现复杂场景深度编排</p></blockquote><table tabindex="0"><thead><tr><th>功能列表</th><th>功能描述</th><th>是否完成</th></tr></thead><tbody><tr><td>SIMPLE 设计器</td><td>仿钉钉/飞书设计器，支持拖拽搭建表单流程，10 分钟快速完成审批流程配置</td><td>✅</td></tr><tr><td>BPMN 设计器</td><td>基于 BPMN 标准开发，适配复杂业务场景，满足多层级审批及流程自动化需求</td><td>✅</td></tr><tr><td>会签</td><td>同一个审批节点设置多个人（如 A、B、C 三人，三人会同时收到待办任务），需全部同意之后，审批才可到下一审批节点</td><td>✅</td></tr><tr><td>或签</td><td>同一个审批节点设置多个人，任意一个人处理后，就能进入下一个节点</td><td>✅</td></tr><tr><td>依次审批</td><td>（顺序会签）同一个审批节点设置多个人（如 A、B、C 三人），三人按顺序依次收到待办，即 A 先审批，A 提交后 B 才能审批，需全部同意之后，审批才可到下一审批节点</td><td>✅</td></tr><tr><td>抄送</td><td>将审批结果通知给抄送人，同一个审批默认排重，不重复抄送给同一人</td><td>✅</td></tr><tr><td>驳回</td><td>（退回）将审批重置发送给某节点，重新审批。可驳回至发起人、上一节点、任意节点</td><td>✅</td></tr><tr><td>转办</td><td>A 转给其 B 审批，B 审批后，进入下一节点</td><td>✅</td></tr><tr><td>委派</td><td>A 转给其 B 审批，B 审批后，转给 A，A 继续审批后进入下一节点</td><td>✅</td></tr><tr><td>加签</td><td>允许当前审批人根据需要，自行增加当前节点的审批人，支持向前、向后加签</td><td>✅</td></tr><tr><td>减签</td><td>（取消加签）在当前审批人操作之前，减少审批人</td><td>✅</td></tr><tr><td>撤销</td><td>（取消流程）流程发起人，可以对流程进行撤销处理</td><td>✅</td></tr><tr><td>终止</td><td>系统管理员，在任意节点终止流程实例</td><td>✅</td></tr><tr><td>表单权限</td><td>支持拖拉拽配置表单，每个审批节点可配置只读、编辑、隐藏权限</td><td>✅</td></tr><tr><td>超时审批</td><td>配置超时审批时间，超时后自动触发审批通过、不通过、驳回等操作</td><td>✅</td></tr><tr><td>自动提醒</td><td>配置提醒时间，到达时间后自动触发短信、邮箱、站内信等通知提醒，支持自定义重复提醒频次</td><td>✅</td></tr><tr><td>父子流程</td><td>主流程设置子流程节点，子流程节点会自动触发子流程。子流程结束后，主流程才会执行（继续往下下执行），支持同步子流程、异步子流程</td><td>✅</td></tr><tr><td>条件分支</td><td>（排它分支）用于在流程中实现决策，即根据条件选择一个分支执行</td><td>✅</td></tr><tr><td>并行分支</td><td>允许将流程分成多条分支，不进行条件判断，所有分支都会执行</td><td>✅</td></tr><tr><td>包容分支</td><td>（条件分支 + 并行分支的结合体）允许基于条件选择多条分支执行，但如果没有任何一个分支满足条件，则可以选择默认分支</td><td>✅</td></tr><tr><td>路由分支</td><td>根据条件选择一个分支执行（重定向到指定配置节点），也可以选择默认分支执行（继续往下执行）</td><td>✅</td></tr><tr><td>触发节点</td><td>执行到该节点，触发 HTTP 请求、HTTP 回调、更新数据、删除数据等</td><td>✅</td></tr><tr><td>延迟节点</td><td>执行到该节点，审批等待一段时间再执行，支持固定时长、固定日期等</td><td>✅</td></tr><tr><td>拓展设置</td><td>流程前置/后置通知，节点（任务）前置、后置通知，流程报表，自动审批去重，自定流程编号、标题、摘要，流程报表等</td><td>✅</td></tr></tbody></table><h3 id="_4-1-bpmn-流程设计器" tabindex="-1">4.1 BPMN 流程设计器 <a class="header-anchor" href="#_4-1-bpmn-流程设计器" aria-label="Permalink to &quot;4.1 BPMN 流程设计器&quot;">​</a></h3><p><img src="'+n+'" alt="BPMN"></p><ul><li><a href="./bpm/model-designer-bpmn">《流程设计器（BPMN）》</a></li><li><a href="./bpm/assignee">《选择审批人、发起人自选》</a></li><li><a href="./bpm/multi-instance">《会签、或签、依次审批》</a></li><li><a href="./bpm/listener">《执行监听器、任务监听器》</a></li><li><a href="./bpm/expression">《流程表达式》</a></li></ul><h3 id="_4-2-钉钉-飞书-流程设计器" tabindex="-1">4.2 钉钉（飞书）流程设计器 <a class="header-anchor" href="#_4-2-钉钉-飞书-流程设计器" aria-label="Permalink to &quot;4.2 钉钉（飞书）流程设计器&quot;">​</a></h3><p><img src="'+h+'" alt="钉钉"></p><ul><li><a href="./bpm/model-designer-dingding">《流程设计器（钉钉、飞书）》</a></li></ul><h3 id="_4-3-审批界面" tabindex="-1">4.3 审批界面 <a class="header-anchor" href="#_4-3-审批界面" aria-label="Permalink to &quot;4.3 审批界面&quot;">​</a></h3><p><img src="'+s+'" alt="审批界面"></p><ul><li><a href="./bpm/use-bpm-form">《审批接入（流程表单）》</a></li><li><a href="./bpm/use-business-form">《审批接入（业务表单）》</a></li><li><a href="./bpm/process-instance">《流程发起、取消、重新发起》</a></li><li><a href="./bpm/task-todo-done">《审批通过、不通过、驳回》</a></li><li><a href="./bpm/sign">《审批加签、减签》</a></li><li><a href="./bpm/task-delegation-and-cc">《审批转办、委派、抄送》</a></li><li><a href="./bpm/message">《流程审批通知》</a></li></ul>',30)])])}const x=a(p,[["render",m]]);export{k as __pageData,x as default};
